+    std::memset(C, 0, n * n * sizeof(float)); // Initialize C to zero
+    std::vector<std::thread> threads;
+    const int num_threads = std::min(n, 10); // Use up to 10 cores
+    int chunk_size = n / num_threads;
+    int remainder = n % num_threads;
+    int current_row = 0;
